public abstract class MotionComponent:HawaComponent {
    protected string kind=>GetType().Name=="RotationComponent"?"rotation":GetType().Name=="TranslationComponent"?"translation":"oscillation";
    protected MotionComponent(string name,string nick,string k):base(name,nick,"Prescribed motion in physical units. Axis uses model coordinates. Ramp uses seconds.","03 Motion"){}
    protected override void RegisterInputParams(GH_InputParamManager p){
        p.AddVectorParameter("Axis","A","Direction in model coordinates",GH_ParamAccess.item,Vector3d.ZAxis);
        p.AddNumberParameter(kind=="rotation"?"RPM":kind=="translation"?"Speed":"Amplitude","V",kind=="rotation"?"Revolutions per minute":kind=="translation"?"Metres per second":"Metres for translation; radians for rotation",GH_ParamAccess.item,kind=="rotation"?10:.1);
        p.AddNumberParameter("Ramp","R","Smooth startup duration in seconds",GH_ParamAccess.item,0);
        if(kind=="oscillation"){p.AddNumberParameter("Frequency","Hz","Cycles per second",GH_ParamAccess.item,.5);p.AddBooleanParameter("Angular","Rot","True pitches about the axis; false translates",GH_ParamAccess.item,false);p.AddNumberParameter("Phase","P","Radians",GH_ParamAccess.item,0);}
    }
    protected override void RegisterOutputParams(GH_OutputParamManager p){p.AddGenericParameter("Motion","M","Prescribed rigid motion",GH_ParamAccess.item);}
    protected override void SolveHawa(IGH_DataAccess da){Vector3d axis=Vector3d.ZAxis;double value=.1,ramp=0,frequency=.5,phase=0;bool angular=false;da.GetData(0,ref axis);da.GetData(1,ref value);da.GetData(2,ref ramp);if(!axis.IsValid||!axis.Unitize()||!double.IsFinite(value)||!double.IsFinite(ramp)||ramp<0)throw new ArgumentException("Finite motion and a nonzero axis required");var motion=new JsonObject{["kind"]="Motion",["type"]=kind,["axis"]=Numbers(new[]{axis.X,axis.Y,axis.Z}),["ramp"]=ramp};motion[kind=="rotation"?"rpm":kind=="translation"?"speed":"amplitude"]=value;if(kind=="oscillation"){da.GetData(3,ref frequency);da.GetData(4,ref angular);da.GetData(5,ref phase);if(!double.IsFinite(frequency)||frequency<0||!double.IsFinite(phase))throw new ArgumentException("Finite nonnegative frequency and finite phase required");motion["frequency"]=frequency;motion["phase"]=phase;motion["mode"]=angular?"rotation":"translation";}da.SetData(0,new HawaGoo(motion));}
}
