public sealed class MovingBodyComponent:HawaComponent {
    private Task<JsonObject>? task;private CancellationTokenSource? cancel;private string? signature;
    public MovingBodyComponent():base("Hawa Moving Body","Body","Prepare a closed rigid mesh once in a background task. Experimental signed-distance representation, half-cell sampling.","02 Geometry"){}
    public override Guid ComponentGuid=>new("a7bb3b0a-ae4f-42ae-9301-a3c55f077142");
    protected override void RegisterInputParams(GH_InputParamManager p){p.AddGenericParameter("Case","C","Base physical Case; uniform BGK",GH_ParamAccess.item);p.AddMeshParameter("Mesh","M","Closed reference mesh",GH_ParamAccess.item);p.AddGenericParameter("Motion","V","Translation, Rotation or Oscillation",GH_ParamAccess.item);p.AddPointParameter("Pivot","P","Rotation pivot in model coordinates",GH_ParamAccess.item);p.AddTextParameter("Body ID","ID","Unique stable body name",GH_ParamAccess.item,"body");}
    protected override void RegisterOutputParams(GH_OutputParamManager p){p.AddGenericParameter("Body","B","Prepared body assigned to this domain",GH_ParamAccess.item);p.AddTextParameter("Report","R","Geometry preparation status",GH_ParamAccess.item);}
    protected override void SolveHawa(IGH_DataAccess da){var spec=ReadObject(da,0);Mesh mesh=null!;da.GetData(1,ref mesh);var motion=ReadObject(da,2);Point3d pivot=default;string id="body";da.GetData(3,ref pivot);da.GetData(4,ref id);if(!mesh.IsValid||!mesh.IsClosed||!pivot.IsValid||string.IsNullOrWhiteSpace(id))throw new ArgumentException("Closed valid mesh, pivot and unique ID required");var key=spec.ToJsonString()+motion.ToJsonString()+mesh.DataCRC(0)+pivot.ToString()+id;
        if(task==null||signature!=key){InputsMissing();signature=key;cancel=new();var token=cancel.Token;var copy=mesh.DuplicateMesh();var world=new JsonObject{["case"]=spec.DeepClone()};double dx=spec["dx"]!.GetValue<double>();
            task=Task.Run(()=>{try{
                for(int i=0;i<copy.Vertices.Count;i++){var p=Coordinates.Grid(world,(Point3d)copy.Vertices[i]);copy.Vertices.SetVertex(i,p[0]!.GetValue<double>()*dx,p[1]!.GetValue<double>()*dx,p[2]!.GetValue<double>()*dx);}
                var bounds=copy.GetBoundingBox(true);var lo=bounds.Min-new Vector3d(dx,dx,dx);double h=dx/2;var size=bounds.Max+new Vector3d(dx,dx,dx)-lo;int[] n={(int)Math.Ceiling(size.X/h)+1,(int)Math.Ceiling(size.Y/h)+1,(int)Math.Ceiling(size.Z/h)+1};if((long)n[0]*n[1]*n[2]>200000)throw new ArgumentException("Body SDF exceeds 200000 samples; use a coarser grid or smaller body");
                var values=new JsonArray();for(int x=0;x<n[0];x++){token.ThrowIfCancellationRequested();for(int y=0;y<n[1];y++)for(int z=0;z<n[2];z++){var point=lo+new Vector3d(x*h,y*h,z*h);var nearest=copy.ClosestPoint(point);double distance=point.DistanceTo(nearest);bool inside=GeometryComponent.Contains(copy,bounds,point,dx*1e-5);values.Add(inside?-distance:distance);}}
                var localMotion=motion.DeepClone().AsObject();var a=motion["axis"]!;var axis=new Vector3d(a[0]!.GetValue<double>(),a[1]!.GetValue<double>(),a[2]!.GetValue<double>());localMotion["axis"]=Numbers(Enumerable.Range(0,3).Select(i=>axis*Coordinates.Axis(world,i)));var pvt=Coordinates.Grid(world,pivot).Select(v=>v!.GetValue<double>()*dx);
                return new JsonObject{["kind"]="Body",["id"]=id,["pivot"]=Numbers(pvt),["motion"]=localMotion,["geometry"]=new JsonObject{["type"]="sdf",["origin"]=Numbers(new[]{lo.X,lo.Y,lo.Z}),["spacing"]=h,["shape"]=new JsonArray(n[0],n[1],n[2]),["values"]=values},["domain_key"]=spec.ToJsonString()};
            }finally{copy.Dispose();}});
        }
        if(!task.IsCompleted){Message="preparing body";string expected=signature!;OnPingDocument()?.ScheduleSolution(100,_=>{if(!Locked&&signature==expected)ExpireSolution(false);});return;}
        if(task.IsFaulted)throw task.Exception!.GetBaseException();if(task.IsCanceled)return;da.SetData(0,new HawaGoo(task.Result));da.SetData(1,"Body prepared; verify thin features and motion clearance");Message="ready";
    }
    protected override void InputsMissing(){cancel?.Cancel();task=null;signature=null;}
    public override void RemovedFromDocument(GH_Document d){InputsMissing();base.RemovedFromDocument(d);}
}

public sealed class MotionCaseComponent:HawaComponent {
    public MotionCaseComponent():base("Hawa Motion Case","MotionCase","Attach prepared rigid bodies to a uniform BGK case. Keep the reference body out of the stationary Geometry input.","04 Case"){}
    public override Guid ComponentGuid=>new("a7bb3b0a-ae4f-42ae-9301-a3c55f077143");
    protected override void RegisterInputParams(GH_InputParamManager p){p.AddGenericParameter("Case","C","Base Case",GH_ParamAccess.item);p.AddGenericParameter("Bodies","B","One to four Moving Body outputs",GH_ParamAccess.list);}
    protected override void RegisterOutputParams(GH_OutputParamManager p){p.AddGenericParameter("Case","C","Moving physical case",GH_ParamAccess.item);}
    protected override void SolveHawa(IGH_DataAccess da){var spec=ReadObject(da,0);var bodies=new List<IGH_Goo>();da.GetDataList(1,bodies);if(bodies.Count<1||bodies.Count>4)throw new ArgumentException("Use one to four bodies");var all=new JsonArray();foreach(var goo in bodies){var body=(goo as HawaGoo)?.Data??throw new ArgumentException("Connect Moving Body outputs");if(body["domain_key"]!.GetValue<string>()!=spec.ToJsonString())throw new ArgumentException("Body belongs to a different case");body.Remove("domain_key");all.Add(body);}var result=spec.DeepClone().AsObject();result["moving_bodies"]=all;result["label"]="Hawa prescribed-motion case";da.SetData(0,new HawaGoo(result));}
}

public sealed class BodyLoadsComponent:HawaQueryComponent {
    public BodyLoadsComponent():base("Hawa Body Loads","Loads","Per-body physical forces and torques in domain axes. Power is fluid work on prescribed bodies. History is bounded to 10000 steps.","06 Results"){}
    public override Guid ComponentGuid=>new("a7bb3b0a-ae4f-42ae-9301-a3c55f077144");
    protected override void RegisterInputParams(GH_InputParamManager p){p.AddGenericParameter("Solution or Frame","S","Live solution or recorded frame",GH_ParamAccess.item);}
    protected override void RegisterOutputParams(GH_OutputParamManager p){p.AddVectorParameter("Force","F","Newtons in model axes",GH_ParamAccess.list);p.AddVectorParameter("Torque","T","Newton metres in model axes",GH_ParamAccess.list);p.AddNumberParameter("Power","P","Watts; signed fluid work on body",GH_ParamAccess.list);p.AddTextParameter("Body IDs","ID","Stable IDs",GH_ParamAccess.list);p.AddGenericParameter("Motion state","M","Poses and load history",GH_ParamAccess.item);}
    protected override void SolveHawa(IGH_DataAccess da){var s=ReadObject(da,0);JsonObject? result;if(s["session"]!=null){var request=Request("body_loads",s["session"]!.GetValue<string>());request["revision"]=s["revision"]?.DeepClone();result=View(request,true);}else{result=s["motion"]?.DeepClone().AsObject()??throw new ArgumentException("Frame has no moving body data");result["case"]=s["case"]!.DeepClone();Message="snapshot";}if(result==null)return;var world=new JsonObject{["case"]=result["case"]!.DeepClone()};var loads=result["loads"]!.AsArray();da.SetDataList(0,loads.Select(l=>Coordinates.Velocity(world,l!["force"]!)));da.SetDataList(1,loads.Select(l=>Coordinates.Velocity(world,l!["torque"]!)));da.SetDataList(2,loads.Select(l=>l!["power"]!.GetValue<double>()));da.SetDataList(3,loads.Select(l=>l!["id"]!.GetValue<string>()));result["kind"]="MotionState";da.SetData(4,new HawaGoo(result));}
}

public sealed class BodyPreviewComponent:HawaComponent {
    public BodyPreviewComponent():base("Hawa Body Preview","BodyView","Transform the reference mesh to its recorded or live body pose. Use the same mesh and ID as Moving Body.","11 Animation"){}
    public override Guid ComponentGuid=>new("a7bb3b0a-ae4f-42ae-9301-a3c55f077145");
    protected override void RegisterInputParams(GH_InputParamManager p){p.AddMeshParameter("Reference mesh","M","Original body mesh",GH_ParamAccess.item);p.AddGenericParameter("Motion state","S","Body Loads motion state",GH_ParamAccess.item);p.AddTextParameter("Body ID","ID","Body to display",GH_ParamAccess.item,"body");}
    protected override void RegisterOutputParams(GH_OutputParamManager p){p.AddMeshParameter("Moved body","M","Body at the field time",GH_ParamAccess.item);}
    protected override void SolveHawa(IGH_DataAccess da){Mesh source=null!;da.GetData(0,ref source);var state=ReadObject(da,1);string id="body";da.GetData(2,ref id);var spec=state["case"]!;var body=spec["moving_bodies"]!.AsArray().FirstOrDefault(b=>b!["id"]!.GetValue<string>()==id)??throw new ArgumentException("Unknown body ID");var pose=state["poses"]!.AsArray().First(p=>p!["id"]!.GetValue<string>()==id)!;var world=new JsonObject{["case"]=spec.DeepClone()};double dx=spec["dx"]!.GetValue<double>();var mesh=source.DuplicateMesh();for(int i=0;i<mesh.Vertices.Count;i++){var q=Coordinates.Grid(world,(Point3d)source.Vertices[i]).Select((v,a)=>v!.GetValue<double>()*dx-body["pivot"]![a]!.GetValue<double>()).ToArray();var r=pose["rotation"]!;var p=Enumerable.Range(0,3).Select(a=>(pose["pivot"]![a]!.GetValue<double>()+Enumerable.Range(0,3).Sum(b=>r[a]![b]!.GetValue<double>()*q[b]))/dx);mesh.Vertices.SetVertex(i,Coordinates.World(world,Numbers(p)));}mesh.Normals.ComputeNormals();da.SetData(0,mesh);}
}

public sealed class MotionEvaluateComponent:HawaComponent {
    private string? job,key;private bool first=true,requireOff;
    public MotionEvaluateComponent():base("Hawa Motion Evaluate","CycleEval","Publish a signed mean force, torque or power after complete prescribed cycles. Connect completed ID and fitness to Hawa Search.","05 Solve"){}
    public override Guid ComponentGuid=>new("a7bb3b0a-ae4f-42ae-9301-a3c55f077146");
    protected override void RegisterInputParams(GH_InputParamManager p){p.AddGenericParameter("Case","C","Motion Case",GH_ParamAccess.item);p.AddNumberParameter("Period","T","Seconds, common period of all bodies",GH_ParamAccess.item,2);p.AddIntegerParameter("Settle cycles","S","Cycles discarded before measurement",GH_ParamAccess.item,1);p.AddIntegerParameter("Measure cycles","N","Whole cycles to measure",GH_ParamAccess.item,1);p.AddTextParameter("Metric","Q","force, torque, power or input_power; signed mean",GH_ParamAccess.item,"input_power");p.AddTextParameter("Body ID","ID","Target body",GH_ParamAccess.item,"body");p.AddIntegerParameter("Axis","A","Force/torque component in domain axes: 0,1,2",GH_ParamAccess.item,0);p.AddBooleanParameter("Enable","E","Start; false cancels",GH_ParamAccess.item,false);p.AddBooleanParameter("Pause","P","Pause at a batch boundary",GH_ParamAccess.item,false);p.AddTextParameter("Device","D","auto, mps, cpu or cuda:0",GH_ParamAccess.item,"auto");}
    protected override void RegisterOutputParams(GH_OutputParamManager p){p.AddNumberParameter("Fitness","F","Completed signed mean only",GH_ParamAccess.item);p.AddGenericParameter("Solution","S","Completed moving session",GH_ParamAccess.item);p.AddTextParameter("Candidate","ID","Completed unique job ID",GH_ParamAccess.item);p.AddTextParameter("Report","R","Window and progress",GH_ParamAccess.item);}
    protected override void SolveHawa(IGH_DataAccess da){bool run=false,pause=false;da.GetData(7,ref run);da.GetData(8,ref pause);if(first){first=false;requireOff=run;}if(!run){requireOff=false;InputsMissing();Message="disabled";return;}if(requireOff){Message="enable again";return;}var spec=ReadObject(da,0);double period=2;int settle=1,cycles=1,axis=0;string metric="input_power",body="body",device="auto";da.GetData(1,ref period);da.GetData(2,ref settle);da.GetData(3,ref cycles);da.GetData(4,ref metric);da.GetData(5,ref body);da.GetData(6,ref axis);da.GetData(9,ref device);var req=new JsonObject{["op"]="evaluate_submit",["kind"]="motion_evaluate",["case"]=spec.DeepClone(),["device"]=device,["period"]=period,["settle_cycles"]=settle,["cycles"]=cycles,["metric"]=metric,["body_id"]=body,["axis"]=axis};string signature=req.ToJsonString();if(job==null||key!=signature){InputsMissing();job=EmbeddedRuntime.Call(req)["job"]!.GetValue<string>();key=signature;}EmbeddedRuntime.Call(new JsonObject{["op"]="evaluate_control",["job"]=job,["action"]=pause?"pause":"resume"});var status=EmbeddedRuntime.Call(new JsonObject{["op"]="evaluate_poll",["job"]=job});string state=status["state"]!.GetValue<string>();Message=state;da.SetData(3,$"{state}: {status["steps"]} iterations");if(state=="failed")throw new Exception(status["error"]!.GetValue<string>());if(state=="completed"){var result=status["result"]!;da.SetData(0,result["fitness"]!.GetValue<double>());da.SetData(1,new HawaGoo(new JsonObject{["kind"]="Solution",["session"]=result["status"]!["session"]!.DeepClone(),["case"]=spec.DeepClone(),["candidate"]=job}));da.SetData(2,job);da.SetData(3,result.ToJsonString());}else{string expected=job;OnPingDocument()?.ScheduleSolution(100,_=>{if(!Locked&&job==expected)ExpireSolution(false);});}}
    internal void RequestCandidate(){InputsMissing();ExpireSolution(false);}
    protected override void InputsMissing(){if(job!=null){try{EmbeddedRuntime.Call(new JsonObject{["op"]="evaluate_control",["job"]=job,["action"]="close"});}catch{}}job=key=null;}
    public override void DocumentContextChanged(GH_Document d,GH_DocumentContext c){if(c==GH_DocumentContext.Close||c==GH_DocumentContext.Unloaded||c==GH_DocumentContext.Lock)requireOff=true;base.DocumentContextChanged(d,c);}
    public override void RemovedFromDocument(GH_Document d){InputsMissing();base.RemovedFromDocument(d);}
}
